@echo off
call %~dp0\set.bat
call "%~dp0..\Service\check_admin_right.bat"

call "%~dp0..\..\..\script\log_for_kill_process.bat" caller "%~0"

Set serUnExe=%~dp0\service_uninstall.exe

if "%architecture%"=="2" (

REM 停止所有服务
echo 停止所有服务
net stop "UnmServiceMonitor"
call %~dp0\delService.bat
for /f "tokens=2 delims=^|" %%i in (%UnmInstallPath%\tools\configedit\Service\unm2000_node.lst) do (
%serUnExe% "%%i"
)
net stop "icegridregistry.UnmBusIceGrid"

net stop "UNMCMAgent"
net stop "UNMCMService"
net stop "UnmCusaServiceMonitor"

REM 杀掉安装目录所有进程
echo 杀掉安装目录所有进程
call "%~dp0kill_all_proces.bat"

REM 卸载所有服务
echo 卸载所有服务

%serUnExe% "UnmServiceMonitor"

if %DeployMode% neq 3 (
%serUnExe% "icegridregistry.UnmBusIceGrid"
%serUnExe% "UNMCMAgent"
%serUnExe% "UNMCMService"
) else (
%serUnExe% "icegridnode.UnmBusIceGrid.UnmRpcNode%HostName%"
%serUnExe% "UNMCMAgent"
)

)

REM 清除临时目录
set iceDefDb=%UnmInstallPath%\server\etc\ice\defaultgrid\db
rd /s /q %iceDefDb%

if "%architecture%"=="1" (

%serUnExe% "UnmCusaServiceMonitor"

rem 卸载网管管理工具
echo 卸载网管管理工具
if exist %UnmInstallPath%\tools\nmtools\unm_cm_agent\uninstall_nmtool_agent.bat (
call %UnmInstallPath%\tools\nmtools\unm_cm_agent\uninstall_nmtool_agent.bat
)

if exist %UnmInstallPath%\tools\nmtools\unm_cm_service\bin\uninstall_nmtool_service.bat (
call %UnmInstallPath%\tools\nmtools\unm_cm_service\bin\uninstall_nmtool_service.bat
)

if exist %UnmInstallPath%\tools\nmtools\unm_cm_service\thirdparty\nginx\uninstall_nmtool_nginx.bat (
call %UnmInstallPath%\tools\nmtools\unm_cm_service\thirdparty\nginx\uninstall_nmtool_nginx.bat
)
echo 网管管理工具卸载完成

echo Kill all processes in the installation directory.
call "%~dp0kill_all_proces.bat"


rem 卸载边车服务
echo 卸载边车服务
if exist %UnmInstallPath%\tools\sidecar\service\stop.bat (
call %UnmInstallPath%\tools\sidecar\service\stop.bat
)

rem 卸载cusa服务
echo 卸载cusa服务
if exist %UnmInstallPath%\tools\server\etc\ice\UNM2000_CUSA\killAllCusaProcess.bat (
call %UnmInstallPath%\tools\server\etc\ice\UNM2000_CUSA\killAllCusaProcess.bat
)
) 


rem 调用jetty卸载脚本
echo 调用jetty服务卸载脚本
if %DeployMode% GEQ 1 if %DeployMode% LEQ 2 (
if exist %UnmInstallPath%\jetty\servicestop.bat call %UnmInstallPath%\jetty\servicestop.bat
)
echo 调用jetty服务卸载脚本完成

rem 调用unm_web_service卸载脚本
echo 调用unm_web_service卸载脚本
if exist %UnmInstallPath%\tools\nginx\script_window\uninstall_service.bat (
	call %UnmInstallPath%\tools\nginx\script_window\uninstall_service.bat
)

REM 调用卸载双因子服务脚本
echo 调用卸载双因子服务脚本
if exist %UnmInstallPath%\platform\jar\authserver\bin\uninstall_authserver.bat (
	call %UnmInstallPath%\platform\jar\authserver\bin\uninstall_authserver.bat
)

REM 删除环境变量
call %~dp0..\env_del.bat
exit /b 0
